/*
 * Geometry helpers for the world-map section.
 *
 * The map's outlines live in `public/map/world.json`, generated by
 * `scripts/build-world-map.mjs`. That file carries its own projection bounds
 * (`w`, `h`, `latMax`, …), and everything here derives pin and arc positions
 * from those shipped numbers rather than from hard-coded copies — so re-running
 * the generator with a different crop moves the geometry and the pins together.
 */

// Surat. Every arc leaves from here, because that is where NV Immigration is.
export const ORIGIN = { lon: 72.83, lat: 21.17, name: 'Surat, India', id: '356' };
// `id` is India's, so the home country can be filled differently from the
// destinations — every arc springs from a point inside it, and leaving it as
// blank as Chad made the busiest point on the map look like open sea.

/*
 * NV's destinations. This is the single source of truth for the country list —
 * LandingPage imports it as its COUNTRIES, so the map and the flag grid below it
 * can never drift apart.
 *
 * `id` is the UN M49 code the TopoJSON source keys geometry by, used to find the
 * matching <path> and light it up. `lon`/`lat` are the capital city, hand-checked
 * — NOT a computed centroid. Two reasons: a centroid of Russia is meaningless
 * because it straddles the antimeridian, and a centroid of a multi-polygon
 * country like Canada or New Zealand can land in open water.
 *
 * Malta, Singapore and Mauritius carry no geometry at this dataset's 110m
 * resolution — they are genuinely smaller than a pixel of it. They are marked
 * `pinOnly` and render as a pin with no outline highlight; moving to the 50m
 * dataset to gain three specks would cost roughly ten times the points for the
 * whole map. `flagOnly` marks "Europe", which is a region rather than a country
 * and so gets neither an outline nor a pin — it stays in the list below the map.
 */
export const DESTINATIONS = [
  { name: 'Canada',      iso: 'CA', group: 'North America', id: '124', lon: -75.70, lat:  45.42 }, // Ottawa
  { name: 'USA',         iso: 'US', group: 'North America', id: '840', lon: -77.04, lat:  38.91 }, // Washington DC
  { name: 'UK',          iso: 'GB', group: 'Europe', id: '826', lon:  -0.13, lat:  51.51 }, // London
  { name: 'Germany',     iso: 'DE', group: 'Europe', id: '276', lon:  13.40, lat:  52.52 }, // Berlin
  { name: 'Poland',      iso: 'PL', group: 'Europe', id: '616', lon:  21.01, lat:  52.23 }, // Warsaw
  { name: 'Malta',       iso: 'MT', group: 'Europe', id: '470', lon:  14.51, lat:  35.90, pinOnly: true },  // Valletta
  { name: 'Russia',      iso: 'RU', group: 'Europe', id: '643', lon:  37.62, lat:  55.75 }, // Moscow
  { name: 'Europe',      iso: 'EU', group: 'Europe', id: null,  lon:  null,  lat:  null, flagOnly: true },
  { name: 'Australia',   iso: 'AU', group: 'Oceania', id: '036', lon: 149.13, lat: -35.28 }, // Canberra
  { name: 'New Zealand', iso: 'NZ', group: 'Oceania', id: '554', lon: 174.78, lat: -41.29 }, // Wellington
  { name: 'Singapore',   iso: 'SG', group: 'Asia', id: '702', lon: 103.82, lat:   1.35, pinOnly: true },  // Singapore
  { name: 'China',       iso: 'CN', group: 'Asia', id: '156', lon: 116.41, lat:  39.90 }, // Beijing
  { name: 'Mauritius',   iso: 'MU', group: 'Africa', id: '480', lon:  57.50, lat: -20.16, pinOnly: true },  // Port Louis
];

// The destinations that actually appear on the map: everything but "Europe".
export const MAP_DESTINATIONS = DESTINATIONS.filter((d) => !d.flagOnly);

/*
 * Equirectangular, mirroring `build-world-map.mjs` exactly. One shared scale for
 * both axes (WIDTH / 360) — using a different vertical scale would stretch the
 * continents away from the shapes people recognise.
 */
export function projectPoint(lon, lat, meta) {
  const w = meta.w;
  return {
    x: ((lon + 180) / 360) * w,
    y: ((meta.latMax - lat) / 360) * w,
  };
}

// Two decimals is well under a device pixel at any size this map renders at, and
// keeps the inline `offset-path` strings that carry these arcs short.
const r = (n) => Math.round(n * 100) / 100;

/*
 * A quadratic Bézier from `a` to `b`, bowed away from the chord.
 *
 * The control point is pushed along one consistent side of the chord's normal,
 * so the arcs read as one family of flight paths rather than a tangle. The side
 * is chosen so the westward routes — six of the twelve destinations are Europe,
 * Russia and North America — bow northward, the shape a real great-circle route
 * takes out of India.
 *
 * `bow` is a fraction of the chord length, so a short hop (Surat → Singapore)
 * and a long haul (Surat → Ottawa) get proportionate curvature instead of the
 * short one looking flat.
 */
export function arcPath(a, b, bow = 0.22) {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const mx = (a.x + b.x) / 2;
  const my = (a.y + b.y) / 2;
  const cx = mx - dy * bow;
  const cy = my + dx * bow;
  return `M${r(a.x)} ${r(a.y)}Q${r(cx)} ${r(cy)} ${r(b.x)} ${r(b.y)}`;
}

/*
 * Top-down airliner silhouette, nose pointing +x, centred on (0, 0).
 *
 * Both of those matter. `offset-rotate: auto` turns the glyph to the route's
 * tangent, which only works if "forward" is +x; and offset-path positions an
 * element by its centre, so a glyph drawn from (0,0) outward would fly along a
 * line parallel to its own route rather than on it.
 *
 * Deliberately chunky — 17 units of wingspan on a 24-unit fuselage. It renders
 * about 13px long on a desktop map, and a scale-accurate airliner (span roughly
 * equal to length, with thin tailplanes) turns to mush at that size.
 */
export const PLANE_PATH =
  'M12 0L5.5 -1.9L2 -2.1L-2.5 -8.5L-5.5 -8.5L-3 -2.1L-7 -1.9L-9 -4.6L-10.8 -4.6'
  + 'L-9.7 -1.5L-12 0L-9.7 1.5L-10.8 4.6L-9 4.6L-7 1.9L-3 2.1L-5.5 8.5L-2.5 8.5'
  + 'L2 2.1L5.5 1.9Z';

/*
 * Draw-on ordering: countries light up west to east, like a sunrise crossing the
 * map. Returns a 0..1 position so the CSS delay is independent of how many
 * countries the dataset happens to contain.
 */
export function waveOrder(countries) {
  const order = new Map();
  [...countries]
    .sort((a, b) => a.cx - b.cx)
    .forEach((c, i) => order.set(c.id, countries.length > 1 ? i / (countries.length - 1) : 0));
  return order;
}
